    ControlRole = apps.get_model('electric_actuators', 'EaControlSignalRole')
    FeedbackRole = apps.get_model('electric_actuators', 'EaFeedbackSignalRole')
    ContactNormal = apps.get_model('electric_actuators', 'EaContactNormal')
    Transport = apps.get_model('electric_actuators', 'EaProtocolTransport')

    fc = {c: _seed(FormCategory, c, n) for c, n in SIGNAL_FORM_CATEGORIES}
    cr = {c: _seed(ControlRole, c, n) for c, n in CONTROL_SIGNAL_ROLES}
    fr = {c: _seed(FeedbackRole, c, n) for c, n in FEEDBACK_SIGNAL_ROLES}
    cn = {c: _seed(ContactNormal, c, n) for c, n in CONTACT_NORMALS}
    tr = {c: _seed(Transport, c, n) for c, n in PROTOCOL_TRANSPORTS}

    for obj in EaSignalForm.objects.all():
        obj.category = fc.get(obj.category_old, fc['contact'])
        obj.save(update_fields=['category'])
    for obj in EaControlSignal.objects.all():
        obj.role = cr.get(obj.role_old, cr['CMD_OCS'])
        obj.save(update_fields=['role'])
    for obj in EaFeedbackSignal.objects.all():
        obj.role = fr.get(obj.role_old, fr['END_OPEN'])
        obj.contact_normal = cn.get(obj.contact_normal_old) if obj.contact_normal_old else None
        obj.save(update_fields=['role', 'contact_normal'])
    for obj in EaCommProtocol.objects.all():
        obj.transport = tr.get(obj.transport_old, tr['other'])
        obj.save(update_fields=['transport'])


